import {pieces,mapAlg} from '../../src/lib/cube';
import type {CubeData,JevRequest} from '../../src/lib/types';
import {observe,aggregate,measuredChecks,planning,situationOptions,type Answers,type Memory} from '../observation-boundary/policy';
import {preconditionObservation,preconditionRequest} from '../../src/server/action-preconditions';
import reference from './routine-reference.json';
export type Ask=(request:JevRequest)=>Promise<Answers>;
const request=(state:unknown,key:string,instructions:string,criteria:Record<string,string>):JevRequest=>({model:'jev-1.13.0',state,questions:{[key]:{type:'choice',instructions,criteria}}});
const uOptions={U:'UF→UL, UL→UB, UB→UR, UR→UF',"U'":'UF→UR, UR→UB, UB→UL, UL→UF',U2:'UF↔UB, UR↔UL'};
const directionNames:Record<string,string>={UF:'front',UR:'right',UB:'back',UL:'left'};
const directionOptions={U:'Quarter turn: front to left; left to back; back to right; right to front.',"U'":'Quarter turn: front to right; right to back; back to left; left to front.',U2:'Half turn: front to back, back to front, left to right, or right to left.'};
export function rotationRequest(currentPosition:string,requiredPosition:string){
 return request({currentPosition:directionNames[currentPosition],requiredPosition:directionNames[requiredPosition]},'setup','Choose the upper-face turn carrying the empty space from its current position to the required position. Read source and destination as an ordered pair. A half turn goes to the opposite side; a quarter turn goes to a neighbouring side. This fixed reference applies to any cube.',directionOptions);
}
export function planRequest(state:CubeData,memory:Memory){
 const o=observe(state,memory),summary=aggregate(measuredChecks(o)),r=planning(o,summary,'player');
 const uncollected=o.edges.filter(p=>summary.checks[`petal_${p.id}`]==='no'&&summary.checks[`bottom_${p.id}`]==='no').length;
 r.state={...r.state as object,uncollectedYellowEdges:uncollected};
 r.questions.goal.instructions='Follow the daisy-first method. uncollectedYellowEdges counts yellow edges that are neither yellow-up petals nor solved bottom edges. If this is greater than zero, choose daisy. If it is zero and counts.bottom is four, choose first-layer. If it is zero and counts.bottom is less than four, choose cross. These are current measurements, not a supplied goal. Preserve existing petals and solved bottom edges.';
 return r;
}
export function focusRequest(state:CubeData,target:string):JevRequest{
 const p=pieces(state).find(p=>p.kind==='edge'&&p.piece===target);
 if(!p)throw new Error('Unknown target');
 return {model:'jev-1.13.0',state:{currentPosition:p.position,yellowDirection:p.stickers.yellow},questions:{
  situation:{type:'choice',instructions:'Classify this selected edge using ONLY currentPosition and yellowDirection. First check yellowDirection=U (petal). Otherwise currentPosition starting D is bottom; starting U is top; all other edge positions are middle. The piece identity is deliberately omitted.',criteria:situationOptions},
  reference:{type:'choice',instructions:'Choose the reference front. If yellowDirection is F/R/B/L, choose that face. If yellowDirection is U or D, choose the other letter of currentPosition. Use current position only.',criteria:{F:'Front F',R:'Front R',B:'Front B',L:'Front L'}},
 }};
}
export async function decide(state:CubeData,ask:Ask,memory:Memory={target:null,recentActions:[]}){
 const plan=await ask(planRequest(state,memory));
 if(plan.goal==='first-layer')return {plan,target:null,front:null,routine:null,preparation:null,alg:''};
 const target=plan.goal==='daisy'?plan.gatherTarget:plan.transferTarget;
 if(target==='none')return {plan,target,front:null,routine:null,preparation:null,alg:''};
 const recognised=await ask(focusRequest(state,target)),front=recognised.reference;
 let routine:string,preparation:string,alg:string,plannedRoutine:string|undefined;
 const recovery:Answers[]=[];
 if(plan.goal==='cross'){
  const obs=preconditionObservation(state,target,front,'daisy-to-cross');
  preparation=(await ask(preconditionRequest(obs,'transfer','rule'))).decision;
  if(preparation==='insert'){routine='daisy-to-cross';alg=mapAlg('F2',front);}
  else {
   const requiredPosition='U'+Object.entries(obs.centers).find(([f,c])=>f!=='U'&&f!=='D'&&c===obs.target.sideColor)![0];
   routine=(await ask(request({currentPosition:obs.target.position,requiredPosition},'setup','Choose the U rotation moving currentPosition to requiredPosition using the fixed cycles. These are present geometric locations, not predicted outcomes.',uOptions))).setup;
   alg=mapAlg(routine,front);
  }
 }else{
  const sample=preconditionObservation(state,target,front,'lift-bottom');
  const ring=['F','R','B','L'],offset=ring.indexOf(front),rename=(f:string)=>ring.includes(f)?ring[(ring.indexOf(f)-offset+4)%4]:f;
  const protectedBottomSlots=pieces(state).filter(p=>p.kind==='edge'&&p.piece.includes('D')&&p.solved).map(p=>[...p.position].map(rename).join(''));
  const rejectedRoutines:string[]=[];
  for(let attempt=0;;attempt++){
   plannedRoutine=(await ask(request({target:sample.target,protectedBottomSlots,previouslyRejectedByModel:rejectedRoutines},'routine','Choose a routine whose position AND yellow direction match the current target, with no affectedBottomSlot in protectedBottomSlots. Ignore landing occupancy for now. Prefer a lift over staging initially. If a previous routine was rejected by the model, choose a different matching routine, including a staging routine. Do not repeat a rejected routine.',{...Object.fromEntries(reference.map(r=>[r.id,JSON.stringify(r)])),reconsider:'No matching routine remains.'}))).routine;
   routine=plannedRoutine;preparation='unassessed';alg='';
   if(routine!=='reconsider'){
    const selected=reference.find(r=>r.id===routine);if(!selected)throw new Error('Unknown routine');
    const obs=preconditionObservation(state,target,front,routine);obs.selectedRoutine.requiredFreeSlots=selected.requiredFreeSlots;
    preparation=(await ask(preconditionRequest(obs,'landing','rule'))).decision;
    if(preparation==='execute'){alg=mapAlg(selected.sequence,front);break;}
    if(preparation==='lower'){routine='lower-top-edge';alg=mapAlg('F',front);break;}
    const freeSlots=Object.entries(obs.yellowUpPetals).filter(([,v])=>!v).map(([s])=>s);
    if(selected.requiredFreeSlots.length===1){
     const freeSlot=(await ask(request({freeSlots},'freeSlot','Choose any currently free slot from freeSlots. This chooses an empty space to bring to the required landing position, not a turn.',Object.fromEntries(['UF','UR','UB','UL'].map(s=>[s,`Choose ${s} only if it occurs in freeSlots`]))))).freeSlot;
     routine=(await ask(rotationRequest(freeSlot,selected.requiredFreeSlots[0]))).setup;
    }else{
     routine=(await ask(request({freeSlots,requiredFreeSlots:selected.requiredFreeSlots},'setup','Choose a U rotation that moves the current freeSlots onto ALL requiredFreeSlots. Track empty spaces, not occupied petals. Rotating preserves the shape of the empty pattern: opposite empties cannot become adjacent empties. Choose reconsider if no rotation works.',{...uOptions,reconsider:'No U rotation makes all required slots free.'}))).setup;
    }
    if(routine!=='reconsider'){alg=mapAlg(routine,front);break;}
   }
   if(attempt>=1)break;
   const decision=await ask(request({selectedRoutine:plannedRoutine,setupAnswer:routine,target:sample.target},'recovery','The selected plan produced no executable move. Decide whether to try a different learned routine for the same target or stop this cycle. Do not invent a move.',{another:'Choose a different routine, possibly staging this edge first',stop:'Stop this cycle for inspection'}));
   recovery.push(decision);
   if(decision.recovery!=='another')break;
   rejectedRoutines.push(plannedRoutine);
  }
 }
 return {plan,target,front,routine,preparation,recognised,plannedRoutine,recovery,alg};
}

scripts/observation-boundary/policy.ts:
// Experimental policy. No evaluator, fixture labels or outcome search may enter this module.
import { colors, pieces, mapAlg } from '../../src/lib/cube';
import { skills } from '../../src/lib/skills';
import type { CubeData, JevRequest, Question } from '../../src/lib/types';
export const VERSION = 'observation-boundary-v1';
export type Boundary = 'code' | 'jev';
export type Wording = 'structured' | 'player';
export type Answers = Record<string, string>;
export const ids = ['DF', 'DR', 'DB', 'DL'];
export const fronts = ['F', 'R', 'B', 'L'];
export const frame = { centers: colors, note: 'Fixed frame: yellow D, white U. Clockwise is viewed directly at the turned face. Camera has no effect.' };
export type Memory = { target: string | null; recentActions: string[] };
export function observe(state: CubeData, memory: Memory = { target: null, recentActions: [] }) {
  return {
    frame,
    edges: pieces(state).filter(p => p.kind === 'edge' && ids.includes(p.piece)).map(p => ({
      id: p.piece, position: p.position, stickers: p.stickers,
    })).sort((a, b) => ids.indexOf(a.id) - ids.indexOf(b.id)),
    memory: { target: memory.target, recentActions: memory.recentActions.slice(-2) },
  };
}
export type Observation = ReturnType<typeof observe>;
export function measuredChecks(o: Observation): Answers {
  return Object.fromEntries(o.edges.flatMap(e => [
    [`petal_${e.id}`, e.stickers.yellow === 'U' ? 'yes' : 'no'],
    [`bottom_${e.id}`, e.stickers.yellow === 'D' && Object.entries(e.stickers).every(([color, face]) => colors[face] === color) ? 'yes' : 'no'],
  ]));
}
export function aggregate(checks: Answers) {
  for (const id of ids) for (const prefix of ['petal', 'bottom'])
    if (!['yes', 'no'].includes(checks[`${prefix}_${id}`])) throw new Error('Missing recognition answer');
  return { checks: { ...checks }, counts: {
    petals: ids.filter(id => checks[`petal_${id}`] === 'yes').length,
    bottom: ids.filter(id => checks[`bottom_${id}`] === 'yes').length,
  } };
}
const q = (instructions: string, criteria: Record<string, string>): Question => ({ type: 'choice', instructions, criteria });
const req = (state: unknown, questions: Record<string, Question>): JevRequest => ({ model: 'jev-1.13.0', state, questions });
function evidence(o: Observation, wording: Wording) {
  if (wording === 'structured') return o;
  return {
    frame: o.frame,
    edges: o.edges.map(e => `Edge ${e.id} is at ${e.position}. ${Object.entries(e.stickers).map(([c, f]) => `${c} faces ${f}`).join('; ')}.`),
    memory: o.memory,
  };
}
export function recognition(o: Observation, wording: Wording) {
  return req(evidence(o, wording), Object.fromEntries(ids.flatMap(id => [
    [`petal_${id}`, q(`Inspect only edge ${id}. Is its yellow sticker facing U? A yellow-up edge on U is a petal; side-center matching is irrelevant.`, { yes: 'Yellow faces U', no: 'Yellow does not face U' })],
    [`bottom_${id}`, q(`Inspect only edge ${id}. Does yellow face D AND does its other sticker face the center of the same color? Read centers from frame. Both conditions must hold.`, { yes: 'Both stickers match their face centers', no: 'At least one sticker does not match its face center' })],
  ])));
}
export const lesson = 'Use the daisy-first beginner method. Preserve petals and correctly solved bottom edges. When bottom=4, hand off to corners. Otherwise, when petals+bottom=4, transfer remaining petals to matching bottom slots. When petals+bottom<4, gather missing petals. Partial transfers must not be rebuilt. Counts describe distinct yellow edges. This experiment stops at a completed cross, not a completed cube.';
export function planning(o: Observation, summary: ReturnType<typeof aggregate>, wording: Wording) {
  const targetOptions = Object.fromEntries([...ids.map(id => [id, `Work on edge ${id}`]), ['none', 'No eligible edge for this hypothetical goal']]);
  return req({ observation: evidence(o, wording), ...summary }, {
    goal: q(lesson, { daisy: 'Gather missing petals', cross: 'Transfer remaining petals', 'first-layer': 'Cross complete: hand off to corners' }),
    gatherTarget: q('Assume the goal is gathering missing petals, regardless of the goal answer in this request. Choose an edge with petal=no AND bottom=no. Preserve both existing petals and solved bottom edges. Prefer an accessible edge; any eligible edge is allowed. If none is eligible, choose none.', targetOptions),
    transferTarget: q('Assume the goal is transferring petals, regardless of the goal answer in this request. Choose an edge with petal=yes AND bottom=no. Any eligible petal is allowed. If none is eligible, choose none.', targetOptions),
  });
}
export const situationOptions = {
  petal: 'Yellow faces U', bottomDown: 'Edge is on D and yellow faces D',
  bottomSide: 'Edge is on D and yellow faces a side', middle: 'Edge is between side faces, not on U or D',
  topSide: 'Edge is on U and yellow faces a side',
};
export function situation(o: Observation, goal: string, target: string, wording: Wording) {
  return req({ observation: evidence(o, wording), goal, target }, {
    situation: q('Classify the selected target using its current position and yellow sticker direction. Do not predict a move.', situationOptions),
    reference: q('Choose a reference front for the selected target. If yellow faces a side, use that side as front. If yellow faces U or D, use the other face in its current position as front. U and D stay fixed. This is based on its CURRENT position, not where it belongs.', Object.fromEntries(fronts.map(f => [f, `Use fixed ${f} as reference front`]))),
  });
}
export const routines = skills.filter(s => s.stages.some(s => s === 'daisy' || s === 'cross'));
// Fixed menu, identical for every cube and both arms. No current-case filtering.
export const actionMenu = Object.fromEntries([
  ...['U', "U'", 'U2'].map(move => [`turn:${move}`, { alg: move, description: `Only ${move}: align a petal with its side center, or clear a landing position before a later lift. Reobserve afterward.` }]),
  ...routines.flatMap(s => ['', 'U', "U'", 'U2'].map(setup => [`${setup || 'none'}:${s.id}`, {
    alg: [setup, s.alg].filter(Boolean).join(' '),
    description: `${setup ? `First ${setup}, then` : 'No setup; execute'} ${s.alg}. ${s.purpose} Setup can move a target on U: applicability must hold AFTER setup. Preserve existing petals when gathering and solved bottom edges throughout.`,
  }])),
  ['reconsider', { alg: '', description: 'No suitable action recognised. Abstain and record this attempt as incomplete.' }],
]) as Record<string, { alg: string; description: string }>;
export function action(o: Observation, summary: ReturnType<typeof aggregate>, goal: string, target: string, recognised: Answers, wording: Wording) {
  const front = recognised.reference;
  if (!fronts.includes(front)) throw new Error('Invalid reference');
  const ring = fronts;
  const local = (f: string) => ring.includes(f) ? ring[(ring.indexOf(f) - ring.indexOf(front) + 4) % 4] : f;
  const localObservation: Observation = {
    ...o, frame: { ...frame, centers: Object.fromEntries(Object.entries(colors).map(([f,c]) => [local(f), c])) },
    edges: o.edges.map(e => ({ ...e, position: [...e.position].map(local).join(''), stickers: Object.fromEntries(Object.entries(e.stickers).map(([c,f]) => [c, local(f)])) })),
  };
  return req({ observation: evidence(localObservation, wording), ...summary, goal, target,
    previousModelAnswers: recognised, reference: `All observation face names and routine moves are local to front=${front}. Piece IDs are identities, not current positions. U/D unchanged.`,
  }, { operation: q('Choose one useful setup/routine for the selected goal and target. Read current stickers and the routine conditions. Use the recognised situation as context. During gather, gain a petal or stage this target for its next lift while protecting existing petals. During transfer, align the target or insert it. Do not move an already solved bottom edge. U-only setup is allowed when it prepares this target. Never assume an action outcome was checked by code.', Object.fromEntries(Object.entries(actionMenu).map(([id, a]) => [id, a.description]))) });
}
export function executeSelection(operation: string, front: string) {
  if (!(operation in actionMenu)) throw new Error('Unknown operation');
  return mapAlg(actionMenu[operation].alg, front);
}
export function provenance(boundary: Boundary) {
  return {
    'observation.frame,edges,memory': 'mechanics: literal centers, positions, sticker directions, previous chosen target and last two executed actions',
    checks: boundary === 'code' ? 'code: color comparisons' : 'JEV: recognition answers copied unchanged',
    counts: 'code: count yes answers; never correct inconsistent recognition',
    'goal,target,situation,reference,operation': 'JEV choices',
    localObservation: 'code: coordinate renaming using JEV-selected reference',
    routines: 'human-authored fixed reference; code executes selected sequence without tactical correction',
  };
}

